inline const SRG *GetSRG(const void *buf) {
  return ::flatbuffers::GetRoot<SRG>(buf);
}

inline const SRG *GetSizePrefixedSRG(const void *buf) {
  return ::flatbuffers::GetSizePrefixedRoot<SRG>(buf);
}

inline const char *SRGIdentifier() {
  return "$SRG";
}

inline bool SRGBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SRGIdentifier());
}

inline bool SizePrefixedSRGBufferHasIdentifier(const void *buf) {
  return ::flatbuffers::BufferHasIdentifier(
      buf, SRGIdentifier(), true);
}

template <bool B = false>
inline bool VerifySRGBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifyBuffer<SRG>(SRGIdentifier());
}

template <bool B = false>
inline bool VerifySizePrefixedSRGBuffer(
    ::flatbuffers::VerifierTemplate<B> &verifier) {
  return verifier.template VerifySizePrefixedBuffer<SRG>(SRGIdentifier());
}

inline void FinishSRGBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SRG> root) {
  fbb.Finish(root, SRGIdentifier());
}

inline void FinishSizePrefixedSRGBuffer(
    ::flatbuffers::FlatBufferBuilder &fbb,
    ::flatbuffers::Offset<SRG> root) {
  fbb.FinishSizePrefixed(root, SRGIdentifier());
}

inline std::unique_ptr<SRGT> UnPackSRG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SRGT>(GetSRG(buf)->UnPack(res));
}

inline std::unique_ptr<SRGT> UnPackSizePrefixedSRG(
    const void *buf,
    const ::flatbuffers::resolver_function_t *res = nullptr) {
  return std::unique_ptr<SRGT>(GetSizePrefixedSRG(buf)->UnPack(res));
}

